<div class="table-responsive"><table class="table admin-table"><thead><tr><th>Order</th><th>Date</th><th>Customer</th><th>Total</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><strong><?= e($o['number']) ?></strong></td><td><?= date('d M Y',strtotime($o['created_at'])) ?></td><td><?= e($o['customer']??'') ?></td><td><?= money($o['total']) ?></td><td><?= e(strtoupper($o['payment_method'])) ?><small class="d-block"><?= e($o['payment_status']) ?></small></td><td><span class="status-pill"><?= e($o['status']) ?></span></td><td><a href="<?= e(url('admin/order',['id'=>$o['id']])) ?>" class="text-link">View →</a></td></tr><?php endforeach ?><?php if(!$orders): ?><tr><td colspan="7" class="empty-table">No orders yet. New orders will appear here.</td></tr><?php endif ?></tbody></table></div>
